#include <cstdio>
#include <algorithm>
#include <vector>
#include <queue>
#include <bitset>
using namespace std;

const int maxn = 210;

struct Node {
    int B, G, R;
    Node(int b = 0, int g = 0, int r = 0) : B(b), G(g), R(r) {}
};

int n;
char s[maxn];
Node start;
vector<int> ans;
bitset<maxn> vis[maxn][maxn];

void BFS() {
    queue<Node> q;

    auto push = [&](int b, int g, int r) {
        if (!vis[b][g][r]) {
            vis[b][g][r] = true;
            q.emplace(b, g, r);
        }
    };

    push(start.B, start.G, start.R);
    ans.clear();

    while (!q.empty()) {
        Node u = q.front();
        q.pop();

        if (u.B == 1 && u.G == 0 && u.R == 0) ans.push_back('B' - 'A');
        if (u.G == 1 && u.B == 0 && u.R == 0) ans.push_back('G' - 'A');
        if (u.R == 1 && u.B == 0 && u.G == 0) ans.push_back('R' - 'A');

        if (u.B >= 2) push(u.B - 1, u.G, u.R);
        if (u.G >= 2) push(u.B, u.G - 1, u.R);
        if (u.R >= 2) push(u.B, u.G, u.R - 1);

        if (u.B >= 1 && u.G >= 1)
            push(u.B - 1, u.G - 1, u.R + 1);
        if (u.B >= 1 && u.R >= 1)
            push(u.B - 1, u.G + 1, u.R - 1);
        if (u.G >= 1 && u.R >= 1)
            push(u.B + 1, u.G - 1, u.R - 1);
    }
}

int main() {
    scanf("%d%s", &n, s);

    for (int i = 0; i < n; ++i) {
        if (s[i] == 'B') ++start.B;
        else if (s[i] == 'G') ++start.G;
        else ++start.R;
    }

    BFS();

    sort(ans.begin(), ans.end());
    ans.erase(unique(ans.begin(), ans.end()), ans.end());

    for (int x : ans) printf("%c", char(x + 'A'));
    printf("\n");

    return 0;
}

