#include <cstdio>
#include <queue>
#include <bitset>

using namespace std;

const int MAXN = 210;

struct Node {
    int b, g, r;
};

bitset<MAXN * MAXN * MAXN> visited;
bool possible[3];

int id(int b, int g, int r) {
    return (b * MAXN + g) * MAXN + r;
}

void pushState(queue<Node>& q, int b, int g, int r) {
    int index = id(b, g, r);
    if (!visited[index]) {
        visited[index] = true;
        q.push({b, g, r});
    }
}

void bfs(Node start) {
    queue<Node> q;
    pushState(q, start.b, start.g, start.r);

    while (!q.empty()) {
        Node u = q.front();
        q.pop();

        if (u.b + u.g + u.r == 1) {
            if (u.b) possible[0] = true;
            if (u.g) possible[1] = true;
            if (u.r) possible[2] = true;
            continue;
        }

        if (u.b >= 2) pushState(q, u.b - 1, u.g, u.r);
        if (u.g >= 2) pushState(q, u.b, u.g - 1, u.r);
        if (u.r >= 2) pushState(q, u.b, u.g, u.r - 1);

        if (u.b && u.g) pushState(q, u.b - 1, u.g - 1, u.r + 1);
        if (u.b && u.r) pushState(q, u.b - 1, u.g + 1, u.r - 1);
        if (u.g && u.r) pushState(q, u.b + 1, u.g - 1, u.r - 1);
    }
}

int main() {
    int n;
    char s[MAXN];
    scanf("%d%s", &n, s);

    Node start{0, 0, 0};
    for (int i = 0; i < n; ++i) {
        if (s[i] == 'B') ++start.b;
        else if (s[i] == 'G') ++start.g;
        else ++start.r;
    }

    bfs(start);

    if (possible[0]) putchar('B');
    if (possible[1]) putchar('G');
    if (possible[2]) putchar('R');
    putchar('\n');

    return 0;
}

#include <cstdio>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    char buffer[1000005];
    if (scanf("%d%s", &n, buffer) != 2) return 0;

    string s(buffer);
    int B = 0, G = 0, R = 0;
    for (char c : s) {
        if (c == 'B') ++B;
        else if (c == 'G') ++G;
        else ++R;
    }

    int size = n + 1;
    vector<unsigned char> current(size * size, 0);
    vector<unsigned char> next(size * size, 0);

    auto index = [size](int b, int g) {
        return b * size + g;
    };

    current[index(B, G)] = 1;

    for (int total = n; total > 1; --total) {
        fill(next.begin(), next.end(), 0);

        for (int b = 0; b <= total; ++b) {
            for (int g = 0; b + g <= total; ++g) {
                int r = total - b - g;
                if (!current[index(b, g)]) continue;

                if (b >= 2) next[index(b - 1, g)] = 1;
                if (g >= 2) next[index(b, g - 1)] = 1;
                if (r >= 2) next[index(b, g)] = 1;

                if (b >= 1 && g >= 1)
                    next[index(b - 1, g - 1)] = 1;
                if (b >= 1 && r >= 1)
                    next[index(b - 1, g + 1)] = 1;
                if (g >= 1 && r >= 1)
                    next[index(b + 1, g - 1)] = 1;
            }
        }

        current.swap(next);
    }

    if (current[index(1, 0)]) putchar('B');
    if (current[index(0, 1)]) putchar('G');
    if (current[index(0, 0)]) putchar('R');
    putchar('\n');

    return 0;
}

#include <cstdio>
#include <string>
#include <vector>
#include <queue>
using namespace std;

struct Node {
    int b, g, r;
};

int main() {
    int n;
    char buffer[205];
    scanf("%d%s", &n, buffer);
    string s(buffer);

    Node start{0, 0, 0};
    for (char c : s) {
        if (c == 'B') ++start.b;
        else if (c == 'G') ++start.g;
        else ++start.r;
    }

    const int base = n + 1;
    const int stateCount = base * base * base;
    vector<bool> visited(stateCount, false);
    queue<int> q;

    auto encode = [base](int b, int g, int r) {
        return (b * base + g) * base + r;
    };

    auto push = [&](int b, int g, int r) {
        int id = encode(b, g, r);
        if (!visited[id]) {
            visited[id] = true;
            q.push(id);
        }
    };

    push(start.b, start.g, start.r);

    bool possibleB = false;
    bool possibleG = false;
    bool possibleR = false;

    while (!q.empty()) {
        int id = q.front();
        q.pop();

        int r = id % base;
        id /= base;
        int g = id % base;
        int b = id / base;

        if (b + g + r == 1) {
            possibleB |= (b == 1);
            possibleG |= (g == 1);
            possibleR |= (r == 1);
            continue;
        }

        if (b >= 2) push(b - 1, g, r);
        if (g >= 2) push(b, g - 1, r);
        if (r >= 2) push(b, g, r - 1);

        if (b >= 1 && g >= 1) push(b - 1, g - 1, r + 1);
        if (b >= 1 && r >= 1) push(b - 1, g + 1, r - 1);
        if (g >= 1 && r >= 1) push(b + 1, g - 1, r - 1);
    }

    if (possibleB) putchar('B');
    if (possibleG) putchar('G');
    if (possibleR) putchar('R');
    putchar('\n');

    return 0;
}

